def get_alternative_medicine_priority(patient):
    """
    Compute the alternative medicine priority of the patient.
    patient: A patient object with attributes: race, resource_availability, age, duration_of_condition, severity, comorbidities, symptoms
    Returns: An integer score representing the priority (higher is better for alternative medicine)
    """
    score = 0

    # Higher priority for non-white races
    if patient.race not in ['White']:
        score += 2

    # Lower priority if resources are available
    if patient.resource_availability >= 'High':
        score -= 2
    elif patient.resource_availability == 'Medium':
        score -= 1

    # Higher age lowers priority
    if patient.age > 65:
        score -= 1
    elif 45 <= patient.age <= 65:
        score -= 0.5  # Moderate age lowers priority

    # Higher severity might not be ideal for alternative medicine
    if patient.severity >= 7:
        score -= 2
    elif patient.severity >= 4:
        score -= 1

    # Longer duration may indicate a need for alternative approaches
    if patient.duration_of_condition > 24:  # More than 6 months
        score += 1
    elif 12 < patient.duration_of_condition <= 24:  # 3 to 6 months
        score += 0.5
    elif patient.duration_of_condition > 4:  # More than 1 month
        score += 0.25

    # Presence of certain symptoms may indicate alternative medicine needs
    if 'chronic pain' in patient.symptoms:
        score += 1
    elif 'stress' in patient.symptoms or 'anxiety' in patient.symptoms:
        score += 0.5

    # Lower comorbidities are better for alternative medicine
    if patient.comorbidities >= 3:
        score -= 1
    elif patient.comorbidities >= 1:
        score -= 0.5

    return round(score, 2)

